// RE-08 (#42) parity harness. `NormalizerParityGolden.swift` was generated by running THIS file with
// RE08_WRITE_GOLDEN=1 against the SwiftSoup-based MediaWikiNormalizer (the commit that adds this
// file); the Swift-HTML port must reproduce every rendering byte for byte. All markup below is
// synthetic MediaWiki-shaped test input written for this repository, not captured upstream content.

private struct ParityCase: Sendable { let name: String; let html: String; var id: Int64 = 11; var revision: Int64 = 22; var key = "Test" }

private func page(_ c: ParityCase) throws -> RESTPage {
    struct Envelope: Encodable, Sendable {
        struct Revision: Encodable, Sendable { let id: Int64; let timestamp = "2026-10-21T00:00:00Z" }
        struct License: Encodable, Sendable { let url = "//creativecommons.org/licenses/by-sa/4.0/"; let title = "CC BY-SA 4.0" }
        let id: Int64; let key: String; let title = "Parity"; let latest: Revision
        let content_model = "wikitext"; let license = License(); let html: String
    }
    let value = try JSONValueEncoder().encodeWithReport(Envelope(id: c.id, key: c.key, latest: .init(id: c.revision), html: c.html)).result
    return try JSONValueDecoder().decodeWithReport(RESTPage.self, from: value).result
}
private func doc(_ body: String, head: String = "", revision: Int = 22, version: String = "2.8.0", bodyVersion: String? = nil,
                 pageID: String = "11", modified: String = "2026-10-21T00:00:00Z") -> String {
    "<!DOCTYPE html><html about='//en.wikipedia.org/wiki/Special:Redirect/revision/\(revision)'><head><meta charset='utf-8'>"
    + "<meta property='mw:htmlVersion' content='\(version)'><meta property='mw:pageId' content='\(pageID)'>"
    + "<meta property='dc:modified' content='\(modified)'>\(head)</head><body data-mw-html-version='\(bodyVersion ?? version)'>\(body)</body></html>"
}
private func sec(_ id: String, _ inner: String) -> String { "<section data-mw-section-id='\(id)'>\(inner)</section>" }
private func ref(_ target: String, href: String? = nil) -> String {
    "<sup class='mw-ref reference' typeof='mw:Extension/ref'><a href='\(href ?? "./Test#\(target)")'><span>[x]</span></a></sup>"
}
private func refs(_ items: [(String, String)]) -> String {
    "<div class='mw-references-wrap'><ol class='mw-references references' typeof='mw:Extension/references'>"
    + items.map { "<li id='\($0.0)'><span class='mw-cite-backlink'><a href='#back'>↑</a></span><span class='mw-reference-text'>\($0.1)</span></li>" }.joined()
    + "</ol></div>"
}

