private func q(_ s: String?) -> String { s.map { String(reflecting: $0) } ?? "nil" }
private func render(_ c: ParityCase) async -> String {
    do {
        let (snapshot, evidence) = try await MediaWikiNormalizer().normalize(page(c), retrievedAt: Date(timeIntervalSince1970: 1_800_000_000), limits: ExplorerLimits())
        let p = snapshot.provenance, id = p.identity
        var lines = ["id=\(id.provider)|\(id.project)|\(id.pageID)|\(id.revisionID)|\(id.normalizerVersion)",
                     "prov=\(q(p.title))|\(q(p.sourceURL))|\(q(p.retrievedAt))|\(q(p.modifiedAt))|\(q(p.language))|\(q(p.license))|\(p.synthetic)"]
        for part in snapshot.parts {
            lines.append("part=\(part.id)|\(q(part.parentID))|\(part.depth)|\(q(part.heading))|\(q(part.text))|\(part.citations.joined(separator: ","))")
        }
        if let references = snapshot.references {
            lines.append("references=\(references.count)")
            for r in references { lines.append("ref=\(r.id)|\(q(r.title))|\(q(r.url))|\(r.synthetic)") }
        } else { lines.append("references=absent") }
        lines.append("tables=\(snapshot.tables == nil ? "nil" : "present")|\(snapshot.tableCount)|bytes=\(snapshot.contentBytes)")
        lines.append("evidence=\(evidence.pageID)|\(evidence.revisionID)|\(evidence.htmlVersion)|\(evidence.htmlSHA256)|\(evidence.nodes)|\(evidence.maximumDepth)")
        return lines.joined(separator: "\n")
    } catch let failure as LiveFailure {
        return "error=LiveFailure.\(failure)"
    } catch let problem as ExplorerProblem {
        return "error=ExplorerProblem.\(problem.code.rawValue)"
    } catch is CancellationError {
        return "error=cancelled"
    } catch {
        // Parser-library error types differ by backend; both reach the provider's sanitizer identically.
        return "error=other"
    }
}

struct NormalizerParityTests {
    @Test func corpusNamesAreUniqueAndCoverSuccessAndDenial() {
        #expect(Set(parityCases.map(\.name)).count == parityCases.count && parityCases.count >= 30)
    }

    @Test func swiftHTMLPortReproducesTheSwiftSoupGoldenRendering() async throws {
        var rendered: [(String, String)] = []
        for c in parityCases { rendered.append((c.name, await render(c))) }
        if ProcessInfo.processInfo.environment["RE08_WRITE_GOLDEN"] == "1" {
            let body = rendered.map { "    \(String(reflecting: $0.0)): \(String(reflecting: $0.1))," }.joined(separator: "\n")
            let source = "// SPDX-License-Identifier: Apache-2.0\n// GENERATED by NormalizerParityTests with RE08_WRITE_GOLDEN=1. Do not edit.\n"
                + "// Producer: SwiftSoup-based MediaWikiNormalizer (see NormalizerParityTests.swift).\n"
                + "let normalizerParityGolden: [String: String] = [\n\(body)\n]\n"
            let target = URL(filePath: #filePath).deletingLastPathComponent().appending(path: "NormalizerParityGolden.swift")
            try Data(source.utf8).write(to: target, options: .atomic)
            return
        }
        #expect(Set(normalizerParityGolden.keys) == Set(parityCases.map(\.name)), "golden and corpus must name the same cases")
        for (name, value) in rendered {
            #expect(value == normalizerParityGolden[name], "parity mismatch: \(name)")
        }
        // The corpus must exercise both accepted documents and fail-closed denials.
        let outcomes = rendered.map(\.1)
        #expect(outcomes.contains { $0.hasPrefix("id=") } && outcomes.contains { $0 == "error=LiveFailure.bodyLimit" })
        #expect(outcomes.contains { $0 == "error=LiveFailure.identity" } && outcomes.contains { $0 == "error=LiveFailure.unsupportedHTML" })
    }
}
